<template>
  <div class="p-4 space-y-2">
    <div class="relative group">
      <div
        class="absolute -inset-2 bg-gradient-to-r from-accent-primary via-accent-secondary to-color2 rounded-3xl  opacity-20 group-hover:opacity-30 transition-opacity duration-500">
      </div>
      
      <div
        class="">

        <!-- Encabezado -->
        <div class="p-6 pb-4 border-b border-slate-200/60 dark:border-slate-700/60">
          <div class="grid grid-cols-1 lg:grid-cols-2 gap-4 items-center">
            <div>
              <div class="flex items-center gap-3 mb-2">
                <div class="w-8 h-8 rounded-xl bg-gradient-to-br from-accent-primary to-color2 flex items-center justify-center shadow-lg">
                  <svg class="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M13 10V3L4 14h7v7l9-11h-7z"/>
                  </svg>
                </div>
                <h2 class="text-2xl font-bold bg-gradient-to-r from-slate-800 to-slate-600 dark:from-slate-200 dark:to-slate-400 bg-clip-text text-transparent">
                  Monitoreo de Potencias
                </h2>
              </div>
              <p class="text-slate-600 dark:text-slate-400 font-medium">
                Potencias en tiempo real: activa (kW), reactiva (kvar) y aparente (kVA)
              </p>
            </div>

            <!-- Leyenda -->
            <div class="flex flex-wrap items-center justify-end gap-6">
              <div class="flex items-center gap-3 px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-800/50 border border-slate-200/60 dark:border-slate-700/60">
                <div class="w-3 h-3 rounded-full bg-gradient-to-r from-accent-primary to-color2 shadow-md"></div>
                <span class="text-sm font-semibold text-slate-700 dark:text-slate-300">kW (Activa)</span>
              </div>
              <div class="flex items-center gap-3 px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-800/50 border border-slate-200/60 dark:border-slate-700/60">
                <div class="w-3 h-3 rounded-full bg-gradient-to-r from-accent-danger to-red-500 shadow-md"></div>
                <span class="text-sm font-semibold text-slate-700 dark:text-slate-300">kvar (Reactiva)</span>
              </div>
              <div class="flex items-center gap-3 px-3 py-2 rounded-xl bg-slate-50 dark:bg-slate-800/50 border border-slate-200/60 dark:border-slate-700/60">
                <div class="w-3 h-3 rounded-full bg-gradient-to-r from-accent-secondary to-cyan-500 shadow-md"></div>
                <span class="text-sm font-semibold text-slate-700 dark:text-slate-300">kVA (Aparente)</span>
              </div>
            </div>
          </div>
        </div>

        <!-- Área del gráfico -->
        <div class="p-6">
          <ApexChart type="line" height="365" :options="chartOptions" :series="series" />
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { computed, defineProps } from "vue"

const props = defineProps({
  chartData: {
    type: Array,
    required: true,
    default: () => []
  }
})

const series = computed(() => [
  { 
    name: "kW (Activa)", 
    data: props.chartData.map(d => d.kW),
    color: '#059669'
  },
  { 
    name: "kvar (Reactiva)", 
    data: props.chartData.map(d => d.kvar),
    color: '#dc2626'
  },
  { 
    name: "kVA (Aparente)", 
    data: props.chartData.map(d => d.kVA),
    color: '#0891b2'
  }
])

const yRange = computed(() => {
  if (!props.chartData.length) return { min: 0, max: 0 }

  const allValues = [
    ...props.chartData.map(d => Number(d.kW) || 0),
    ...props.chartData.map(d => Number(d.kvar) || 0),
    ...props.chartData.map(d => Number(d.kVA) || 0)
  ]

  return {
    min: Math.min(...allValues),
    max: Math.max(...allValues)
  }
})


const chartOptions = computed(() => ({
  chart: {
    type: "line",
    zoom: { enabled: true },
    toolbar: { 
      show: true,
      tools: {
        download: true,
        selection: true,
        zoom: true,
        zoomin: true,
        zoomout: true,
        pan: true,
        reset: true
      }
    },
    background: 'transparent',
    fontFamily: 'Inter, system-ui, sans-serif',
    animations: {
      enabled: true,
      easing: 'easeinout',
      speed: 800
    }
  },
 grid: {
    show: false 
  },
  xaxis: {
    type: "category",
    tickAmount: 24,
    categories: props.chartData.map(d => d.datetime),
    axisBorder: {
      show: true,
      color: '#475569',
      height: 2
    },
    axisTicks: {
      show: true,
      color: '#475569',
      height: 6
    },
    labels: {
      rotate: -45,
      style: { colors: '#475569', fontSize: '12px', fontWeight: '500' }
    },
    title: {
      text: "Tiempo",
      style: { color: "#334155", fontSize: "12px", fontWeight: "600" }
    }
  },
 yaxis: {
  min: yRange.value.min,
  max: yRange.value.max,
  axisBorder: {
    show: true,
    color: '#475569'
  },
  axisTicks: {
    show: true,
    color: '#475569'
  },
  title: {
    text: "Potencia (kW / kvar / kVA)",
    style: { color: "#475569", fontSize: "14px", fontWeight: "600" }
  },
  labels: {
    style: { colors: '#64748b', fontSize: '12px', fontWeight: '500' },
    formatter: (val) => `${val} u`
  }
},
  stroke: {
    curve: "smooth",
    width: 2.5,
    lineCap: 'round'
  },
  colors: ["#1e7f14", "#ef4444", "#3b82f6"],
  legend: { show: false },
  tooltip: {
    theme: 'light',
    style: { fontSize: '12px' },
    marker: { show: true },
    y: {
      formatter: (val, { seriesIndex }) => {
        if (seriesIndex === 0) return `${val} kW`
        if (seriesIndex === 1) return `${val} kvar`
        if (seriesIndex === 2) return `${val} kVA`
        return val
      }
    }
  },
  markers: {
    size: 0,
    hover: { size: 8, sizeOffset: 3 }
  }
}))
</script>
